{
  "implementation": "def solve(case):
    payload = case['payload']
    nodes = payload['nodes']
    required_symbols = payload['required_symbols']
    node_map = {n['id']: n for n in nodes}
    children_map = {n['id']: [] for n in nodes}
    for n in nodes:
        p = n['parent']
        if p is not None:
            children_map.setdefault(p, []).append(n['id'])
    initial_ids = set(n['id'] for n in nodes)
    if 'root' not in node_map:
        raise ValueError('Missing root')
    root_id = 'root'
    for sym in required_symbols:
        if not any(n['symbol'] == sym for n in nodes):
            raise ValueError(f'Required symbol {sym} not present')
    retained = set(initial_ids)
    removal_order = []
    # Sort all node ids by depth descending, then id ascending
    all_ids_sorted = sorted(
        [n['id'] for n in nodes],
        key=lambda x: (-node_map[x]['depth'], x)
    )
    for nid in all_ids_sorted:
        if nid not in retained:
            continue
        node = node_map[nid]
        # Cannot remove root, required symbol, or non-removable
        if nid == root_id or node['symbol'] in required_symbols or not node['removable']:
            continue
        # Check for retained children
        has_retained_child = any(cid in retained for cid in children_map.get(nid, []))
        if has_retained_child:
            continue
        # Tentatively remove - check required symbols still present
        retained_test = set(retained)
        retained_test.remove(nid)
        symbols_after = set(node_map[nid2]['symbol'] for nid2 in retained_test)
        if all(sym in symbols_after for sym in required_symbols):
            retained.remove(nid)
            removal_order.append(nid)
    return {
        'retained': sorted(retained),
        'removal_order': removal_order
    }"
}
